def process(sp3Paths) -> pd.DataFrame:
    import pandas as pd
    import numpy as np
    from datetime import datetime

    def parse_sp3_positions(path: str) -> pd.DataFrame:
        rows = []
        cur_t = None
        # SP3 positions are typically in km in ITRF (ECEF). We take P* records for Swarm-A.
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                if not line:
                    continue
                if line.startswith("*"):
                    # Example: *  2019  9  2 23 59 42.00000000
                    parts = line.strip().split()
                    if len(parts) >= 7:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        sec = float(parts[6])
                        isec = int(sec)
                        usec = int(round((sec - isec) * 1e6))
                        cur_t = datetime(y, mo, d, hh, mm, isec, usec)
                    else:
                        cur_t = None
                elif line.startswith("P") and cur_t is not None:
                    # Satellite identifier in cols 2-4 typically. We'll accept any starting with 'A' after 'P'.
                    # Many Swarm SP3 use IDs: 'L47' etc, but for Swarm-A often 'SWA' or 'A'. We'll be robust.
                    sat = line[1:4].strip()
                    if sat.upper() in ["SWA", "A", "SW", "SA"] or sat.upper().endswith("A"):
                        # x y z clock (km, km, km, microseconds)
                        try:
                            x = float(line[4:18])
                            y = float(line[18:32])
                            z = float(line[32:46])
                        except Exception:
                            # fallback split parse
                            sp = line.split()
                            if len(sp) >= 4:
                                x, y, z = map(float, sp[1:4])
                            else:
                                continue
                        rows.append({"time": cur_t, "xKm": x, "yKm": y, "zKm": z, "sat": sat, "source": path})
        return pd.DataFrame(rows)

    # parse all files
    all_df = []
    for p in sp3Paths["path"].tolist():
        dfp = parse_sp3_positions(p)
        if len(dfp) > 0:
            all_df.append(dfp)

    if not all_df:
        raise ValueError("No Swarm-A position records found in supplied SP3 files.")

    out = pd.concat(all_df, ignore_index=True)

    # Keep only 2019-09-02 to 2019-09-29 inclusive (UTC)
    out = out[(out["time"] >= pd.Timestamp("2019-09-02")) & (out["time"] < pd.Timestamp("2019-09-30"))]

    return out.sort_values(["time"]).reset_index(drop=True)

def process(interpGeopotential) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    # If phi is present (J/kg), use it; otherwise fall back to mgh using constant g.
    g0 = 9.80665
    if 'phiJperKg' in interpGeopotential.columns and interpGeopotential['phiJperKg'].notna().any():
        phi = interpGeopotential['phiJperKg'].astype(float).to_numpy()
    else:
        phi = g0 * interpGeopotential['altM'].astype(float).to_numpy()

    mean_phi = float(np.nanmean(phi))
    return pd.DataFrame([{
        'meanGeopotentialEnergyJperKg': mean_phi,
        'n': int(len(phi)),
        'phiMin': float(np.nanmin(phi)),
        'phiMax': float(np.nanmax(phi))
    }])

def process(interpGeopotential) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    g0 = 9.80665
    df = interpGeopotential.copy()

    if df is None or len(df) == 0:
        return pd.DataFrame([{
            'meanGeopotentialEnergyJperKg': np.nan,
            'n': 0,
            'phiMin': np.nan,
            'phiMax': np.nan
        }])

    if 'phiJperKg' in df.columns and df['phiJperKg'].notna().any():
        phi = pd.to_numeric(df['phiJperKg'], errors='coerce')
    else:
        # fallback: simple phi = g*h
        phi = g0 * pd.to_numeric(df.get('altM', np.nan), errors='coerce')

    phi = phi.replace([np.inf, -np.inf], np.nan).dropna()

    return pd.DataFrame([{
        'meanGeopotentialEnergyJperKg': float(phi.mean()) if len(phi) else np.nan,
        'n': int(len(phi)),
        'phiMin': float(phi.min()) if len(phi) else np.nan,
        'phiMax': float(phi.max()) if len(phi) else np.nan
    }])

