                    if m:
                        current_time = to_dt(*m.groups())
                    else:
                        current_time = None
                elif line.startswith('P') and current_time is not None:
                    m = pos_re.match(line)
                    if not m:
                        continue
                    sat = m.group(1)
                    if sat != 'L01':
                        continue
                    x = float(m.group(2)); y = float(m.group(3)); z = float(m.group(4)); clk = float(m.group(5))
                    r = (x*x + y*y + z*z) ** 0.5
                    if 6000 <= r <= 8000:
                        rows.append({
                            'time': current_time,
                            'xKm': x,
                            'yKm': y,
                            'zKm': z,
                            'clockMicrosec': clk,
                            'sp3Path': pth,
                            'satId': sat
                        })

    df = pd.DataFrame(rows)
    if df.empty:
        return df

    df = df.sort_values('time')
    # constrain to Sep 2-30 window, but meanEnergy will apply Sep2-29 implicitly by file coverage
    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')
    df['time'] = pd.to_datetime(df['time'], utc=True)
    df = df[(df['time'] >= start) & (df['time'] < end)]

    df = df.drop_duplicates(subset=['time'])
    return df.reset_index(drop=True)

def process(sp3Paths) -> pd.DataFrame:
    import pandas as pd
    import re
    from datetime import datetime, timezone

    paths = sp3Paths['path'].tolist()

    epoch_re = re.compile(r"^\*\s+(\d{4})\s+(\d{2})\s+(\d{2})\s+(\d{2})\s+(\d{2})\s+([0-9.]+)")
    pos_re = re.compile(r"^P(\S{3})\s+(-?\d+\.\d+)\s+(-?\d+\.\d+)\s+(-?\d+\.\d+)\s+(-?\d+\.\d+)")

    rows = []
    current_time = None

    def to_dt(y, mo, d, hh, mm, ss_float):
        sec_int = int(float(ss_float))
        frac = float(ss_float) - sec_int
        micro = int(round(frac * 1e6))
        if micro >= 1000000:
            sec_int += 1
            micro -= 1000000
        return datetime(int(y), int(mo), int(d), int(hh), int(mm), sec_int, micro, tzinfo=timezone.utc)

    for pth in paths:
        with open(pth, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    m = epoch_re.match(line)
                    current_time = to_dt(*m.groups()) if m else None
                    continue
                if line.startswith('P') and current_time is not None:
                    m = pos_re.match(line)
                    if not m:
                        continue
                    sat = m.group(1)
                    if sat != 'L01':
                        continue
                    x = float(m.group(2)); y = float(m.group(3)); z = float(m.group(4)); clk = float(m.group(5))
                    r = (x*x + y*y + z*z) ** 0.5
                    if 6000 <= r <= 8000:
                        rows.append({'time': current_time, 'xKm': x, 'yKm': y, 'zKm': z,
                                     'clockMicrosec': clk, 'sp3Path': pth, 'satId': sat})

    df = pd.DataFrame(rows)
    if df.empty:
        return df

    df['time'] = pd.to_datetime(df['time'], utc=True)
    df = df.sort_values('time')

    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')
    df = df[(df['time'] >= start) & (df['time'] < end)]

    df = df.drop_duplicates(subset=['time'], keep='first')
    return df.reset_index(drop=True)

def process(meanEnergy) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    if meanEnergy is None or len(meanEnergy) == 0:
        return pd.DataFrame({'final': ['nan']})

    v = meanEnergy['meanGeopotentialEnergyJperKg'].iloc[0]
    try:
        v = float(v)
    except Exception:
        v = np.nan

    if not np.isfinite(v):
        return pd.DataFrame({'final': ['nan']})

    return pd.DataFrame({'final': [f"{v:.2f}"]})
